Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_enough_space_no_resize(void) {
    // Setup: create a buffer with enough space to prepend without resizing
    // Initial buffer data: "world"
    // Prepend string: "hello "
    // Buffer's allocated size (len) must be > strlen("hello ") + strlen("world") = 6 + 5 = 11
    // Let's use len = 20 for safety

    const char *initial_data = "world";
    const char *to_prepend = "hello ";
    const char *expected = "hello world";

    // Create buffer with initial data and enough space
    buffer_t *buf = helper_make_buffer_with_data_and_size((char *)initial_data, 20);
    TEST_ASSERT_NOT_NULL(buf);

    // Call function under test
    int ret = buffer_prepend(buf, (char *)to_prepend);

    // Assertions
    TEST_ASSERT_EQUAL(0, ret);
    helper_assert_buffer_data_equals(buf, expected);
    helper_assert_buffer_length(buf, strlen(expected));
    TEST_ASSERT_TRUE(buf->len > strlen(expected)); // Still enough space

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_enough_space_no_resize);
    return UNITY_END();
}


